declare const require:any,process:any,__dirname:string;
export {};
const {Worker}=require('node:worker_threads');
async function main(){
 const inputs=JSON.parse(process.argv[2]);const results:any[]=[];
 let completed=0;const worker=new Worker(__dirname+'/worker.js');
 try{
  await new Promise<void>((resolve,reject)=>{
   if(!inputs.length){resolve();return;}
   worker.on('error',reject);
   worker.on('message',(m:any)=>{
    if(m.error){reject(new Error(m.error));return;}
    results[m.id]=m.value; completed++;
    if(completed===inputs.length)resolve();
   });
   inputs.forEach((input:any,id:number)=>worker.postMessage({id,input}));
  });
  console.log(JSON.stringify(results));
 } finally {await worker.terminate();}
}
main().catch(e=>{console.error(String(e));process.exitCode=1;});
